```python
import requests
from pathlib import Path
from typing import Callable, Optional
from warnings import warn

def get_data(url: str, timeout: float = 10, headers: Optional[Dict[str, str]] = None) -> Dict[str, str]:
    """
    Fetch data from a remote URL with a given timeout.

    Args:
        url (str): The URL to fetch data from.
        timeout (float, optional): The time in seconds to wait for a response to be received. Defaults to 10.
        headers (Optional[Dict[str, str]], optional): A dictionary of headers to include in the request. Defaults to None.

    Returns:
        Dict[str, str]: The response from the server as a dictionary.
    """

    try:
        response = requests.get(url, timeout=timeout, headers=headers)
        if response.status_code == 200:
            return response.json()
        else:
            return {
                "status_code": response.status_code,
                "error": "Failed to fetch data. Status code: {}".format(response.status_code)
            }
    except requests.exceptions.Timeout as e:
        warn("Timeout error occurred", category=RuntimeError)
        return {
            "status_code": e.response.status_code,
            "error": ".Timeout error: {}".format(str(e))
        }
    except requests.exceptions.RequestException as e:
        warn("General request error occurred", category=RuntimeError)
        return {
            "status_code": e.response.status_code,
            "error": str(e)
        }

# Example usage:
url = "https://example.com/api/data"
data = get_data(url)

for item, value in data.items():
    print(f"{item}: {value}")
```

