import functools

class Cache:
    def __init__(self):
        self.cache = {}

    @functools.lru_cache(maxsize=None)
    def expensive_operation(self, data):
        # expensive computation
        return result  # return the result

    @property
    def cache_key(self):
        return self.cache

    @cache_key.setter
    def cache_key(self, value):
        self.cache[value] = None

def get_cache_operation(data):
