from enum import Enum
from typing import Mapping, List, Iterator, Any

class StatusCode(Enum):
    PASSED = 0
    FAIL = 1
    BOTH = 2
    TIMEOUT = 3

class StatusCodeChecker:
    """Custom status code checker."""

    def __init__(self):
        self.statuses = {
            StatusCode.PASSED: "passed",
            StatusCode.FAIL: "failed",
            StatusCode.BOTH: "both",
            StatusCode.TIMEOUT: "timeout"
        }

    def __contains__(self, value):
        """Check if a value matches any status code."""
        return StatusCode(value in self.statuses.keys())

    def __contains_key(self, key):
        """Check if a key is in self-statues."""
        return key in self.statuses

def get_status_code(status_checker, status, message):
    """Get a status code from a checker and a message."""
    return getattr(status_checker, status, getattr(status_checker, StatusCode.TIMEOUT)(message))(message)

def run_test(status_checker, test, message):
    """Run a test and return a status code."""
    return get_status_code(status_checker, test, message)

class Example:
    """Example class with a status code property."""

    def __init__(self):
        self.code: int = None

    @property
    def status(self) -> StatusCode:
        """Get the status code."""
        return getattr(self, 'code', StatusCode.TIMEOUT)

    def set_code(self, code: int):
        """Set a status code."""
        self.code = code
        self._validate_code()

    def _validate_code(self):
        """Validate a status code."""
        if not self.code in StatusCodeChecker.statuses:
            raise ValueError("Invalid status code")
        if isinstance(self.code, StatusCode) and self.code.value == StatusCode.BOTH:
            raise ValueError("Both statuses can't be both")
        if isinstance(self.code, int):
            if self.code < 0:
                raise ValueError("Negative status codes are not supported")

class RunTestCase:
