        run_test(Example(), "Successful test", "Output: Hello World")

    def test_fail(self) -> None:
        """Test that a test fails with an empty output."""
        run_test(Example(), "Failed test", "No output")

    def test_both(self) -> None:
        """Test that both test sets a status to both."""
        example = Example()
        example.set_code(StatusCode.BOTH)
        example._validate_code()

    def test_timeout(self) -> None:
