            "id": self.id,
            "name": self.name,
            "description": self.description,
        }

    @classmethod
    def get_from_path(cls, path: Path):
        name, permission = path.split("_")
        return {
            field: value.strip() for field in name.split("_") for value in permission.split(":")
        }

