        self公開: Dict[str, set] = {}
        self.processes: Dict[str, Process] = {}

    def subscribe(self, topic: str, callback: any) -> None:
        if topic in self.public:
            raise ValueError("Topic already subscribed")
        self.subscribe_name = f"{topic}_{uuid4().hex}"
        self.public[topic].append(self.processes[self.publish_name] = Process(topic, self.queue])
        self.subscribers.setdefault(self.process_name, []).append(callback)
        log.info(f"Subscribed: {topic} -> {self.process_name}({', '.join(map(str, self.public[topic]))}")

    def publish(self, topic: str, message: Any) -> None:
        for process in self.processes[self.public[topic]]:
            process.publish(message)
        for subscriber, callback in self.subscribers.pop(self.process_name, ()):
            try:
                callback(message)
            except Exception as e:
                log.error(f"Error: {e} -> {str(e)}")
            except ValueError as e:
                log.error(f"Error: {e} -> {str(e)}")

